// Collects the colour parsing cases from web-platform-tests.
//
// The cases are not scraped with a regular expression, because half of them are
// generated by a loop in the test file itself — `color()` is tested once per
// colour space that way. Instead the test file's own script is run with the
// harness functions replaced by recorders, so whatever the file generates is
// what comes out, and a change on their side shows up as a change here.
//
// Usage, from the repository root:
//
//   node scripts/wpt.mjs wpt.tsv
//
// Then `python scripts/fixtures.py wpt wpt.tsv src/wpt_wbtest.mbt`.
//
// The output is tab separated: `valid` or `invalid`, the input, and the
// serialisation the test expects, empty where the test only says it parses.

import { writeFileSync } from "node:fs";

const BASE =
  "https://raw.githubusercontent.com/web-platform-tests/wpt/master/css/css-color/parsing/";

// The helpers a few of the files use (`fuzzy_test_valid_color` and friends).
// The harness itself is not taken from WPT: it needs a document, and everything
// it would do with one is done here by a recorder instead.
const SUPPORT =
  "https://raw.githubusercontent.com/web-platform-tests/wpt/master/css/support/color-testcommon.js";

// The files that only need a value to be read: no layout, no cascade, no
// computed style. The `color-computed-*` files ask a browser to resolve a
// declaration, which is a different question from whether it parses.
const FILES = [
  "color-valid.html",
  "color-invalid.html",
  "color-valid-rgb.html",
  "color-invalid-rgb.html",
  "color-valid-hsl.html",
  "color-invalid-hsl.html",
  "color-valid-hwb.html",
  "color-invalid-hwb.html",
  "color-valid-lab.html",
  "color-invalid-lab.html",
  "color-valid-color-function.html",
  "color-invalid-color-function.html",
  "color-invalid-named-color.html",
  "color-computed-named-color.html",
];

const support = (await fetch(SUPPORT).then((response) => {
  if (!response.ok) {
    throw new Error(`color-testcommon.js: ${response.status}`);
  }
  return response.text();
  // The file opens with a strict-mode directive; the test files assign to a
  // global without declaring it, so strict mode has to go.
})).replace(/^\s*['"]use strict['"];/, "");

const cases = [];

function record(kind, property, value, expected) {
  if (property !== "color") return;
  cases.push([kind, String(value), expected === undefined ? "" : String(expected)]);
}

const harness = {
  test_valid_value: (property, value, expected) => record("valid", property, value, expected),
  test_invalid_value: (property, value) => record("invalid", property, value),
  test_computed_value: (property, value, expected) => record("valid", property, value, expected),
  test: (name, body) => {
    if (typeof body === "function") body();
  },
  assert_true() {},
  assert_equals() {},
};

function scriptOf(html) {
  // Every inline <script> body, in order, joined: a couple of the files put the
  // table and the loop that walks it in separate blocks.
  const bodies = [...html.matchAll(/<script(?![^>]*\bsrc=)[^>]*>([\s\S]*?)<\/script>/g)].map(
    (match) => match[1],
  );
  return bodies.join("\n");
}

for (const file of FILES) {
  const response = await fetch(BASE + file);
  if (!response.ok) {
    throw new Error(`${file}: ${response.status}`);
  }
  const html = await response.text();
  const source = scriptOf(html);
  const names = Object.keys(harness);
  const values = names.map((name) => harness[name]);
  try {
    // `new Function` is sloppy mode, which the test files need: they assign to
    // `tests` without declaring it.
    new Function(...names, support + "\n" + source)(...values);
  } catch (error) {
    throw new Error(`${file}: ${error.message}`);
  }
}

// A value may contain newlines — CSS treats them as ordinary whitespace, and a
// couple of the cases keep one to check that — so they become spaces here: the
// table is line based.
const lines = cases.map((fields) =>
  fields.map((field) => field.replace(/[\t\n\r]+/g, " ").trim()).join("\t"),
);
writeFileSync(process.argv[2] ?? "wpt.tsv", lines.join("\n") + "\n");
console.log(`${cases.length} cases from ${FILES.length} files`);
